using UnityEngine;
namespace Alterverse.Match
{
public sealed class DimensionsFrontVisual:MonoBehaviour
{
[SerializeField]private float arenaHalfWidth=39f;[SerializeField]private float frontLength=68f;[SerializeField]private float smoothing=6f;[SerializeField]private int segmentCount=25;[SerializeField]private float waveAmplitude=.75f;[SerializeField]private float waveSpeed=1.15f;
private DimensionsFront front;private Transform[] segments;private Renderer[] segmentRenderers;private float targetX;private readonly Color zeroColor=new(.55f,.08f,.82f),lumenColor=new(.08f,.72f,.78f);
private void Start(){front=Object.FindAnyObjectByType<DimensionsFront>();BuildFront();if(front!=null){targetX=ControlToX(front.LumenControl);front.ControlChanged+=OnControlChanged;}else targetX=0f;}
private void BuildFront(){segmentCount=Mathf.Max(7,segmentCount);segments=new Transform[segmentCount];segmentRenderers=new Renderer[segmentCount];float step=frontLength/(segmentCount-1);for(int i=0;i<segmentCount;i++){GameObject piece=GameObject.CreatePrimitive(PrimitiveType.Cube);piece.name=$"AV_RealityFront_{i:00}";piece.transform.SetParent(transform,false);piece.transform.position=new Vector3(0,.12f,-frontLength*.5f+i*step);piece.transform.localScale=new Vector3(.38f,.1f,step*1.08f);Collider c=piece.GetComponent<Collider>();if(c!=null)c.enabled=false;segments[i]=piece.transform;segmentRenderers[i]=piece.GetComponent<Renderer>();}}
private void Update(){if(segments==null)return;float t=Time.time;float control=front!=null?front.LumenControl:50f;Color baseColor=Color.Lerp(zeroColor,lumenColor,control/100f);for(int i=0;i<segments.Length;i++){Transform s=segments[i];if(s==null)continue;float normalized=i/(float)(segments.Length-1);float wave=Mathf.Sin(t*waveSpeed+i*.72f)*waveAmplitude+Mathf.Sin(t*.63f+i*1.37f)*waveAmplitude*.32f;float desiredX=targetX+wave;Vector3 p=s.position;p.x=Mathf.Lerp(p.x,desiredX,1f-Mathf.Exp(-smoothing*Time.deltaTime));p.y=.12f+(.025f*Mathf.Sin(t*4.5f+i*.8f));s.position=p;float pulse=.88f+Mathf.Sin(t*5f+i*.55f)*.12f;Vector3 scale=s.localScale;scale.x=.32f+pulse*.16f;scale.y=.08f+pulse*.05f;s.localScale=scale;if(segmentRenderers[i]!=null){float shimmer=.12f*Mathf.Sin(t*2.2f+normalized*8f);segmentRenderers[i].material.color=Color.Lerp(baseColor,Color.white,Mathf.Max(0f,shimmer));}}}
private void OnControlChanged(float zero,float lumen){targetX=ControlToX(lumen);}private float ControlToX(float lumen)=>Mathf.Lerp(arenaHalfWidth,-arenaHalfWidth,lumen/100f);private void OnDestroy(){if(front!=null)front.ControlChanged-=OnControlChanged;}
}}
